    return (StringBuffer('GameMessage(')
          ..write('id: $id, ')
          ..write('sessionId: $sessionId, ')
          ..write('role: $role, ')
          ..write('content: $content, ')
          ..write('messageType: $messageType, ')
          ..write('savepointLabel: $savepointLabel, ')
          ..write('timestamp: $timestamp')
          ..write(')'))
        .toString();
  }

